 for(std::size_t i=0;i<cfg.grammar.operators.size();++i){if(i)effective<<',';effective<<static_cast<unsigned>(cfg.grammar.operators[i]);}effective<<"],\"grammar_iteration_nesting\":1,\"terminal_bounds\":true,\"per_row\":{\"visits\":100000,\"operations\":100000,\"workspace\":1048576,\"per_operation_iterations\":2048,\"aggregate_iterations\":32768,\"nesting\":2},\"per_loss\":{\"visits\":50000000,\"operations\":50000000,\"iterations\":20000000}}";write(output/(resume.empty()?"effective.json":"resume-effective.json"),effective.str());
 std::unique_ptr<DiscreteEvolutionRun> run;if(resume.empty())run=std::make_unique<DiscreteEvolutionRun>(p,cfg,random);else run=DiscreteEvolutionRun::restore(loadDiscreteRunCheckpoint(resume),p,cfg,random);
 const auto initial=run->population().bestSeen();const double initialLoss=initial?initial->fitness():-1;const auto initialGeneration=*run->population().generation();
 std::ofstream journal(output/(resume.empty()?"progress.jsonl":"resume-progress.jsonl"));if(!journal)throw std::runtime_error("metrics file open");std::uint64_t reportRows=0,reportVisits=0,reportOps=0,reportIterations=0;std::string stop="running",failure;std::uint64_t lastGeneration=initialGeneration,attainmentGeneration=initialGeneration,attainmentAttempts=run->work().lossAttempts;double previousLoss=initialLoss;
