 std::ostringstream s;s<<std::setprecision(17)<<"{\"version\":1,\"kind\":"<<quote(kind)<<",\"task\":"<<quote(task)<<",\"generation\":"<<*run->population().generation()<<",\"attempted_generations\":"<<run->algorithm().attempts()<<",\"candidate_requests\":"<<random.evaluationAttempts()<<",\"work\":"<<workJson(before)<<",\"seconds\":"<<elapsed()<<",\"loss\":"<<best->fitness()<<",\"canonical\":"<<quote(best->text())<<",\"pretty\":"<<quote(formatDiscreteExpression(best->expression()))<<",\"nodes\":"<<best->expression().nodeCount()<<",\"depth\":"<<best->expression().depth()<<",\"training\":"<<metrics(m)<<",\"stop\":"<<quote(stop)<<",\"reporting_rows\":"<<reportRows<<",\"reporting_visits\":"<<reportVisits<<",\"reporting_operations\":"<<reportOps<<",\"reporting_iterations\":"<<reportIterations<<",\"reporting_loss_attempts\":0}";journal<<s.str()<<'\n';journal.flush();if(!journal)throw std::runtime_error("metrics write");std::cout<<task<<" generation="<<*run->population().generation()<<" attempts="<<before.lossAttempts<<'/'<<cfg.maxLossAttempts<<" matches="<<m.matches<<'/'<<m.rows<<" loss="<<best->fitness()<<" nodes="<<best->expression().nodeCount()<<" depth="<<best->expression().depth()<<" seconds="<<elapsed()<<" visits="<<before.nodeVisits<<" iterations="<<before.iterations<<" stop="<<stop<<'\n'<<best->text()<<'\n'<<formatDiscreteExpression(best->expression())<<'\n'<<std::flush;
