 catch(const std::exception& e){failure=e.what();auto error=std::current_exception();stop=resourceFailure(error)?"resource_exhausted":isEvaluationBudget(error)?"loss_budget":isEvaluationCancelled(error)?"cancelled":"operational_failure";}
