 const double searchSeconds=elapsed();const auto training=assess(best->expression(),p->rows());const auto held=assessmentRows(task,task=="primality"?64:1001,task=="primality"?255:1200);const auto exterior=task=="primality"?assessmentRows(task,256,1024):std::vector<DiscreteRegressionRow>{};const auto h=assess(best->expression(),held),x=assess(best->expression(),exterior);struct rusage usage{};if(getrusage(RUSAGE_SELF,&usage)!=0)throw std::runtime_error("rusage failure");
